#!/usr/bin/env python3
"""Build the provider-neutral data type/shape research registries.

The source lists below are curated hypotheses. Generation removes clerical repetition; it does not
turn a candidate into a verified type or manufacture types by a Cartesian product of facets.
"""

from __future__ import annotations

import json
from collections import Counter
from pathlib import Path


ROOT = Path(__file__).resolve().parent
ACCESSED = "2026-08-25"


def write_json(name: str, value: object) -> None:
    (ROOT / name).write_text(json.dumps(value, indent=2, ensure_ascii=False) + "\n")


def write_jsonl(name: str, records: list[dict]) -> None:
    text = "".join(json.dumps(record, sort_keys=True, ensure_ascii=False) + "\n" for record in records)
    (ROOT / name).write_text(text)


def source(
    number: int,
    title: str,
    publisher: str,
    source_kind: str,
    authority: str,
    url: str,
    supports: list[str],
    limitations: list[str],
    edition: str = "",
) -> dict:
    record = {
        "source_id": f"DSS-{number:03d}",
        "title": title,
        "publisher": publisher,
        "source_kind": source_kind,
        "authority": authority,
        "url": url,
        "supports": supports,
        "limitations": limitations,
        "accessed_at": ACCESSED,
    }
    if edition:
        record["edition_or_version"] = edition
    return record


