def carrier(
    name: str,
    definition: str,
    parameters: list[str],
    equality: list[str],
    order: list[str],
    arithmetic: list[str],
    evidence: list[str],
    aliases: list[str] | None = None,
) -> dict:
    type_id = f"dt.carrier.{name}"
    return {
        "type_id": type_id,
        "record_kind": "carrier_type",
        "name": name.replace("_", " "),
        "definition": definition,
        "status": "candidate",
        "owner_context": "bc.carrier_representation",
        "parameters": parameters,
        "parent_type_ids": [],
        "allowed_carriers": [type_id],
        "equality_laws": equality,
        "order_laws": order,
        "arithmetic_laws": arithmetic,
        "invalid_inferences": ["Carrier equality or arithmetic does not establish semantic equality or valid domain arithmetic."],
        "missingness": {**DEFAULT_MISSINGNESS, "allowed_reasons": []},
        "uncertainty": {"model": "not_expressed_by_carrier", "propagation_required": False},
        "time_semantics": {"role": "none_unless_logical_time_carrier", "timezone_or_calendar_required": False},
        "provenance": DEFAULT_PROVENANCE,
        "canonicalization": {"rule": "Requires the named carrier profile, parameters and encoding edition.", "digest_safe_without_profile": False},
        "compatibility": {"relation": "carrier-level representability", "loss_conditions": ["range", "precision", "normalization", "unsupported parameter"]},
        "evidence_refs": evidence,
        "compiler_obligations": ["range_check", "parameter_check", "encoding_profile_check", "do_not_infer_semantics"],
        "aliases": aliases or [],
        "extension_point": False,
    }


