def shape(
    name: str,
    family: str,
    definition: str,
    owner: str,
    element_kind: str,
    cardinality: str,
    homogeneity: str,
    key_required: bool,
    key_scope: str,
    topology_kind: str,
    directed: bool | None,
    order_kind: str,
    order_status: str,
    time_roles: list[str],
    interval_support: bool,
    calendar_required: bool,
    change_modes: list[str],
    finality: str,
    constraints: list[str],
    valid_ops: list[str],
    invalid_ops: list[str],
    bindings: list[str],
    loss_risks: list[str],
    evidence: list[str],
    parents: list[str] | None = None,
    parameters: list[str] | None = None,
    extension: bool = False,
) -> dict:
    return {
        "shape_id": f"shape.{name}",
        "name": name.replace("_", " "),
        "family": family,
        "definition": definition,
        "status": "candidate",
        "owner_context": owner,
        "parent_shape_ids": parents or [],
        "parameters": parameters or [],
        "element_contract": {"kind": element_kind, "cardinality": cardinality, "homogeneity": homogeneity},
        "keys": {"required": key_required, "uniqueness_scope": key_scope},
        "topology": {"kind": topology_kind, "directed": directed},
        "ordering": {"kind": order_kind, "semantic_or_incidental": order_status},
        "time_semantics": {"roles": time_roles, "interval_support": interval_support, "calendar_required": calendar_required},
        "change_semantics": {"modes": change_modes, "finality": finality},
        "constraints": constraints,
        "valid_operations": [f"op.{op}" for op in valid_ops],
        "invalid_operations": invalid_ops,
        "representation_bindings": bindings,
        "information_loss_risks": loss_risks,
        "evidence_refs": evidence,
        "compiler_obligations": ["resolve_element_types", "validate_shape_constraints", "preserve_keys_order_time_change", "check_operation_domain", "refuse_unsupported_representation"],
        "extension_point": extension,
    }


