def operation_profile(name: str) -> tuple[str, dict]:
    groups = [
        (STRUCTURAL_OPS, "structural"), (RELATIONAL_OPS, "relational"), (ARRAY_OPS, "array"),
        (TEMPORAL_OPS, "temporal"), (GRAPH_OPS, "graph"), (SPATIAL_OPS, "spatial"),
        (SIGNAL_MEDIA_OPS, "signal_media"), (UNCERTAINTY_OPS, "uncertainty"),
        (PROCESS_OPS, "process"), (OPTIMIZATION_OPS, "optimization"),
        (SIMULATION_OPS, "simulation"), (ARTIFACT_OPS, "artifact"),
        (TELEMETRY_OPS, "telemetry"), (SEMANTIC_OPS, "semantic"),
    ]
    matches = [group for members, group in groups if name in members]
    if len(matches) != 1:
        raise ValueError(f"operation {name!r} belongs to {matches or 'no profile'}")
    return matches[0], OP_PROFILES[matches[0]]


OPERATIONS = sorted({operation.removeprefix("op.") for record in SHAPES for operation in record["valid_operations"]})
TOTALITY_MATRIX = []
for op_name in OPERATIONS:
    group_name, profile = operation_profile(op_name)
    totality = profile["totality"]
    loss = profile["loss"]
    determinism = profile["determinism"]
    state = profile["state"]
    preconditions = ["Input contract is resolved and validates.", "Resource and precision budgets are declared where material."]
    failures = ["invalid_input", "unsupported_semantics", "resource_budget_exceeded"]
    if op_name in OP_OVERRIDES:
        totality, loss, determinism, state, preconditions, failures = OP_OVERRIDES[op_name]
    TOTALITY_MATRIX.append({
        "matrix_id": f"otm.{op_name}",
        "operation_id": f"op.{op_name}",
        "owner_context": profile["owner"],
        "input_domain": profile["input"],
        "output_domain": profile["output"],
        "totality": totality,
        "preconditions": preconditions,
        "failure_modes": failures,
        "information_loss": loss,
        "determinism": determinism,
        "statefulness": state,
        "evidence_refs": profile["evidence"],
    })


