def crosswalk(
    number: int,
    source_representation: str,
    source_record_ids: list[str],
    target_record_ids: list[str],
    preservation: str,
    owner: str,
    evidence: list[str],
    preserved: list[str],
    risks: list[str],
) -> dict:
    return {
        "crosswalk_id": f"xwalk.{number:03d}",
        "source_representation": source_representation,
        "source_layer": "encoding_container_or_layout",
        "source_record_ids": source_record_ids,
        "target_representation": "provider-neutral data type/shape graph",
        "target_layer": "carrier_logical_or_semantic",
        "target_record_ids": target_record_ids,
        "direction": "bidirectional_under_profile" if preservation == "lossless_under_profile" else "one_way_or_profile_dependent",
        "preservation": preservation,
        "prerequisites": ["Exact source edition/profile is resolved.", "All target semantic parameters and qualifiers are supplied or the conversion refuses.", "Resource and recursion limits are declared."],
        "preserved_semantics": preserved,
        "lost_or_at_risk": risks,
        "failure_modes": ["unsupported_construct", "unresolved_semantics", "unrepresentable_value", "resource_budget_exceeded", "round_trip_mismatch"],
        "evidence_refs": evidence,
        "test_obligations": ["positive_fixture", "negative_fixture", "boundary_fixture", "round_trip_or_declared_loss_fixture"],
        "owner_context": owner,
        "status": "candidate",
    }


