def invalid_inference(
    number: int,
    source_assertion: str,
    invalid_conclusion: str,
    owner: str,
    evidence: list[str],
    affected: list[str],
    required: list[str],
) -> dict:
    return {
        "inference_id": f"infer.invalid.{number:03d}",
        "source_assertion": source_assertion,
        "invalid_conclusion": invalid_conclusion,
        "why_invalid": "The source assertion is compatible with multiple meanings or states; the conclusion introduces information not contained in the source contract.",
        "required_evidence": required,
        "affected_records": affected,
        "owner_context": owner,
        "evidence_refs": evidence,
        "severity": "error",
        "compiler_behavior": "refuse_or_emit_typed_unresolved_semantic_gap",
        "refusal_code": f"DATA_INVALID_INFERENCE_{number:03d}",
        "status": "candidate",
    }


